  bulkOffer = true;
  try {
    for (const id of ids) {
      if (busyCount() >= officeLv().proj) break;
      const o = S.offers.find(x => x.id === id); if (!o) continue;
      acceptOffer(id);
      const p = projects.find(q => q.id === id);
      if (p) { won++; money += p.reward; last = p; } else if (!S.offers.some(x => x.id === id)) lost++;
    }
  } finally { bulkOffer = false; }
