  el.innerHTML = `<img src="${pic}" alt=""><div class="sp-cap">${cap}</div><div class="sp-sub">${sub}</div><div class="sp-sub" style="font-size:12px;opacity:.6">клик — продължи</div>`;
  document.body.appendChild(el);
