  el.onclick = close; requestAnimationFrame(() => requestAnimationFrame(() => el.classList.add('on')));
  setTimeout(close, 7000); if (feature('snd-lvup2')) Sound.play('lvup'); else if (!splashFanfare()) Sound.play('levelup');
