    let q = x.want;
    const qt = econ.quoteMaterial(x.m, q, connected(), supplyOpts());
    if (qt.total > left) q = Math.floor(q * left / qt.total);
    while (q > 0 && econ.quoteMaterial(x.m, q, connected(), supplyOpts()).total > Math.min(left, econ.money)) q--;
