  if (!econ.canAfford(L.cost)) { withLoan(L.cost, `${L.nm} в ${cityById(id).nm}`, () => buildPort(id, free)); return; }
  econ.spend(L.cost, 'покупка', `${L.nm} в ${cityById(id).nm}`);
