    if (id === S.cityId) { const g = sellUnit(t, true); if (!g) break; got += g; n++; continue; }
    const c = garCity(id), j = (c.units || []).indexOf(t); if (j < 0) break;
    c.units.splice(j, 1); (c.unitXp || []).splice(j, 1); got += econ.sellUnit(t); n++;
