for (const c of ECON.COMPANIES) if (c.cc && !TAKEOVER[c.id]) TAKEOVER[c.id] = { b: [['house', 2], ['office', 1]], units: ['crew', 'crew', 'loader', 'truck'] };   // чуждите строителни фирми
