  if (T.stock) v += T.stock * ['sand', 'gravel', 'concrete', 'bricks', 'steel', 'wood', 'glass'].reduce((a, m) => a + (ECON.MATERIALS[m]?.buyPrice || 0), 0) * 0.9;
  if (T.land) v += T.land * LAND_PRICE.outer;
