const YEAR = 360, LIFE = 5 * YEAR, WEAR = 40 / 180;      // 100% → 60% за ~половин година
const NEXT_KIND = { house: 'shop', shop: 'office', office: 'tower', tower: 'tower' };
const condOf = o => o.cond ?? 100;
