const RELIEF = { bg: { img: 'assets/ui/bg-relief.webp', x: -235.17, y: -165, w: 485.04, h: 330 }, eu: { img: 'assets/ui/eu-relief.webp', x: -2675.09, y: -2875, w: 3895.05, h: 3750 } };
